public static TFMRegistrationCollectorSummary SummaryStep(  int      _id,
                                                                str      _name,
                                                                str      _header,
                                                                str      _label,
                                                                str      _helpLabel,
                                                                boolean  _optional=false)
{
    TFMRegistrationCollectorSummary collector = new TFMRegistrationCollectorSummary(_id,_name,_header,_label,_helpLabel);
    collector.parmOptional(_optional);
    return collector;
}

/// <summary>
/// Builds a registration collector for signature input
/// </summary>
/// <param name="_stepsElement"></param>
/// <param name="_id"></param>
/// <param name="_name"></param>
/// <param name="_header"></param>
/// <param name="_label"></param>
/// <param name="_helpLabel"></param>
/// <param name="_optional"></param>
public client server static Map SummaryStepMap(          int      _id,
                                                           str      _name,
                                                           str      _header,
                                                           str      _label,
                                                           str      _helpLabel,
                                                           boolean  _optional=false)
{
    return TFMRegistrationCollectorSummary::SummaryStep(_id,_name,_header,_label,_helpLabel,_optional).getMap();
}
